package com.backendSupermercado.supermercasdo.modules.reportes.compras.controller;
import java.time.LocalDate; import java.util.*; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import com.backendSupermercado.supermercasdo.modules.reportes.compras.model.TipoReporteCompras; import com.backendSupermercado.supermercasdo.modules.reportes.compras.repository.ReporteComprasRepository; import com.backendSupermercado.supermercasdo.modules.reportes.venta.dto.ReporteVentaExportacion; import com.backendSupermercado.supermercasdo.modules.reportes.venta.service.*;
@RestController @RequestMapping("/api/reportes/compras") public class ReporteComprasController { private final ReporteComprasRepository repo;private final ReporteVentaPdfService pdf;private final ReporteVentaExcelService excel;public ReporteComprasController(ReporteComprasRepository r,ReporteVentaPdfService p,ReporteVentaExcelService e){repo=r;pdf=p;excel=e;} @GetMapping("/{tipo}") public Page<Map<String,Object>> consultar(@PathVariable String tipo,@RequestParam Map<String,String>f,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="10")int size){return repo.consultar(TipoReporteCompras.desdeRuta(tipo).ruta(),n(f),PageRequest.of(page,size));} @GetMapping(value="/{tipo}/pdf",produces=MediaType.APPLICATION_PDF_VALUE)public ResponseEntity<byte[]> pdf(@PathVariable String tipo,@RequestParam Map<String,String>f){TipoReporteCompras t=TipoReporteCompras.desdeRuta(tipo);return archivo(pdf.generar(exportar(t,n(f))),"reporte-compras-"+t.ruta()+".pdf",MediaType.APPLICATION_PDF);}@GetMapping(value="/{tipo}/excel",produces="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")public ResponseEntity<byte[]> excel(@PathVariable String tipo,@RequestParam Map<String,String>f){TipoReporteCompras t=TipoReporteCompras.desdeRuta(tipo);return archivo(excel.generar(exportar(t,n(f))),"reporte-compras-"+t.ruta()+".xlsx",MediaType.parseMediaType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"));}private ReporteVentaExportacion exportar(TipoReporteCompras t,Map<String,Object>f){List<Map<String,Object>>d=repo.consultar(t.ruta(),f,Pageable.unpaged()).getContent();List<String>c=t==TipoReporteCompras.RECEPCIONES?List.of("Fecha","Proveedor","Estado","Productos"):t==TipoReporteCompras.COMPARATIVO?List.of("Código","Producto","Solicitado","Recibido","Faltante"):t==TipoReporteCompras.PROVEEDORES?List.of("Proveedor","Pedidos","Total comprado"):t==TipoReporteCompras.PRODUCTOS?List.of("Código","Producto","Cantidad","Costo total"):t==TipoReporteCompras.RENTABILIDAD?List.of("Código","Producto","Costo promedio","Precio venta","Ganancia estimada"):t==TipoReporteCompras.DEVOLUCIONES?List.of("Fecha","Proveedor","Estado","Motivo","Cantidad"):t==TipoReporteCompras.CUMPLIMIENTO?List.of("Proveedor","Pedidos","Recepciones"):t==TipoReporteCompras.PERIODOS?List.of("Fecha","Pedidos","Proveedores"):List.of("Fecha","Pedidos","Recepciones","Devoluciones");List<List<String>>rows=d.stream().map(x->{List<String>r=new ArrayList<>();if(t==TipoReporteCompras.RECEPCIONES)for(String k:List.of("fecha","proveedor","estado","productos"))r.add(v(x,k));else if(t==TipoReporteCompras.COMPARATIVO)for(String k:List.of("codigo","producto","solicitado","recibido","faltante"))r.add(v(x,k));else if(t==TipoReporteCompras.PROVEEDORES)for(String k:List.of("proveedor","pedidos","total"))r.add(v(x,k));else if(t==TipoReporteCompras.PRODUCTOS)for(String k:List.of("codigo","producto","cantidad","costo"))r.add(v(x,k));else if(t==TipoReporteCompras.RENTABILIDAD)for(String k:List.of("codigo","producto","costo","precio","ganancia"))r.add(v(x,k));else if(t==TipoReporteCompras.DEVOLUCIONES)for(String k:List.of("fecha","proveedor","estado","motivo","cantidad"))r.add(v(x,k));else if(t==TipoReporteCompras.CUMPLIMIENTO)for(String k:List.of("proveedor","pedidos","recepciones"))r.add(v(x,k));else if(t==TipoReporteCompras.PERIODOS)for(String k:List.of("fecha","pedidos","proveedores"))r.add(v(x,k));else if(t==TipoReporteCompras.ABASTECIMIENTO)for(String k:List.of("fecha","pedidos","recepciones","devoluciones"))r.add(v(x,k));else for(String k:List.of("fecha","proveedor","estado","productos"))r.add(v(x,k));return r;}).toList();return new ReporteVentaExportacion(t.titulo(),"Filtros aplicados: "+f,c,rows);}private String v(Map<String,Object>m,String k){return m.get(k)==null?"-":String.valueOf(m.get(k));}private Map<String,Object>n(Map<String,String>i){Map<String,Object>o=new LinkedHashMap<>();i.forEach((k,v)->{if(v!=null&&!v.isBlank())try{o.put(k,k.endsWith("Id")?Long.valueOf(v):v);}catch(Exception e){throw new IllegalArgumentException("Filtro inválido");}});return o;}private ResponseEntity<byte[]>archivo(byte[]b,String n,MediaType m){return ResponseEntity.ok().contentType(m).contentLength(b.length).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+n+"\"").header("X-Generated-Date",LocalDate.now().toString()).body(b);}}
